    // For a secure implementation, password hashing (e.g., bcrypt) and salting would be essential.
    db.get(
      'SELECT userInfo FROM users WHERE username = ? AND password = ?',
      [username, password],
      (err, row) => {
        if (err) {
          reject(err);
        } else {
          resolve(row ? row.userInfo : null);
        }
      }
    );
  });
}
